from datetime import datetime
from sqlalchemy import Boolean, DateTime, ForeignKey, Integer, Numeric, String, Text, func
from sqlalchemy.orm import Mapped, mapped_column, relationship
from .core.database import Base
class Timestamp: created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now()); updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now(),onupdate=func.now())
class AdminUser(Timestamp,Base):
    __tablename__="admin_users"; id:Mapped[int]=mapped_column(primary_key=True); email:Mapped[str]=mapped_column(String(255),unique=True,index=True); password_hash:Mapped[str]=mapped_column(String(255)); is_active:Mapped[bool]=mapped_column(Boolean,default=True); last_login:Mapped[datetime|None]=mapped_column(DateTime(timezone=True))
class Property(Timestamp,Base):
    __tablename__="properties"; id:Mapped[int]=mapped_column(primary_key=True); title:Mapped[str]=mapped_column(String(255)); slug:Mapped[str]=mapped_column(String(280),unique=True,index=True); description:Mapped[str|None]=mapped_column(Text); location:Mapped[str|None]=mapped_column(String(255),index=True); city:Mapped[str|None]=mapped_column(String(100)); state:Mapped[str|None]=mapped_column(String(100)); property_type:Mapped[str|None]=mapped_column(String(40),index=True); status:Mapped[str]=mapped_column(String(20),default="draft",index=True); price:Mapped[float|None]=mapped_column(Numeric(14,2),index=True); currency:Mapped[str|None]=mapped_column(String(8)); area:Mapped[str|None]=mapped_column(String(100)); bedrooms:Mapped[int|None]=mapped_column(Integer); bathrooms:Mapped[int|None]=mapped_column(Integer); featured:Mapped[bool]=mapped_column(Boolean,default=False,index=True); images:Mapped[list["PropertyImage"]]=relationship(back_populates="property",cascade="all, delete-orphan")
class PropertyImage(Base):
    __tablename__="property_images"; id:Mapped[int]=mapped_column(primary_key=True); property_id:Mapped[int]=mapped_column(ForeignKey("properties.id",ondelete="CASCADE")); image_url:Mapped[str]=mapped_column(String(1000)); alt_text:Mapped[str|None]=mapped_column(String(255)); sort_order:Mapped[int]=mapped_column(Integer,default=0); created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now()); property:Mapped[Property]=relationship(back_populates="images")
class Enquiry(Timestamp,Base):
    __tablename__="enquiries"; id:Mapped[int]=mapped_column(primary_key=True); name:Mapped[str]=mapped_column(String(120)); email:Mapped[str]=mapped_column(String(255)); phone:Mapped[str|None]=mapped_column(String(50)); requirement:Mapped[str|None]=mapped_column(String(120)); message:Mapped[str]=mapped_column(Text); status:Mapped[str]=mapped_column(String(20),default="new",index=True)
class ConsultationRequest(Base):
    __tablename__="consultation_requests"; id:Mapped[int]=mapped_column(primary_key=True); name:Mapped[str]=mapped_column(String(120)); email:Mapped[str]=mapped_column(String(255)); phone:Mapped[str|None]=mapped_column(String(50)); preferred_contact_method:Mapped[str|None]=mapped_column(String(40)); requirement:Mapped[str|None]=mapped_column(String(120)); message:Mapped[str|None]=mapped_column(Text); status:Mapped[str]=mapped_column(String(20),default="new",index=True); created_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now())
class BusinessSettings(Base):
    __tablename__="business_settings"; id:Mapped[int]=mapped_column(primary_key=True); business_name:Mapped[str]=mapped_column(String(255)); email:Mapped[str]=mapped_column(String(255)); phone:Mapped[str]=mapped_column(String(50)); address:Mapped[str]=mapped_column(String(500)); city:Mapped[str]=mapped_column(String(100)); state:Mapped[str]=mapped_column(String(100)); postal_code:Mapped[str]=mapped_column(String(20)); country:Mapped[str]=mapped_column(String(100),default="India"); website:Mapped[str]=mapped_column(String(255)); updated_at:Mapped[datetime]=mapped_column(DateTime(timezone=True),server_default=func.now(),onupdate=func.now())
